window.MG_LAZY_DATA["data/lazy/resources/comm-v28-072-780a61f8d4c74b22.json"]={sha256:"780a61f8d4c74b22696685e0b606e743a2916fe8b8131985a8554b53c66f9c90",value:{"sources":[{"id":"v28-case-12394b4a22706b67","url":"https://ocw.mit.edu/courses/6-450-principles-of-digital-communications-i-fall-2006/","title":"Principles of Digital Communications I","titleEn":"Principles of Digital Communications I","publisher":"MIT OpenCourseWare","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"comm-v28-072","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"comm-v28-072","related":[{"id":"comm-v28-073","referenceUrls":["https://www.analog.com/en/resources/technical-articles/system-noisefigure-analysis-for-modern-radio-receivers.html"],"title":"Armstrong 超外差：鏡像頻率的雙重映射","titleEn":"Armstrong superheterodyne: the two-frequency image mapping","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 2000000 symbol/s 與 1600000 symbol/s，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 2000000 symbol/s and 1600000 symbol/s, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋120 MHz與140 MHz，建立frequency_plan.csv、欲收/鏡像兩條路徑、預選器查核表，並完成以下驗收：預選器必須在鏡像頻率提供題設所需抑制；提高IF只改變濾波難度，不能單憑鏡像遠離宣告合格。","differenceEn":"Derive and explain 120 MHz and 140 MHz; create frequency_plan.csv, desired/image paths and a preselector checklist; apply this acceptance decision: The preselector must meet the specified image attenuation; increasing IF changes filter difficulty but does not itself establish acceptance.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 升餘弦通帶所需頻寬 B=(1+alpha)Rs；固定頻寬時滾降增加會降低可容納符元率。 展開基準式 2400000/(1+0.2)；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：把兩個符元率代回頻寬式，均應得到2.4 MHz；用頻譜圖標出正負頻率與通帶定義。 將兩條推導一起存入 pulse_budget.csv、頻譜邊界圖、ISI待測清單。","從原理 混頻差頻為abs(fRF-fLO)。高側注入下，欲收與鏡像都可落入同一IF，IF濾波器無法事後分離。 展開基準式 100+2*10；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：列舉欲收與鏡像對LO的差頻：100/120對110均為10；100/140對120均為20。 將兩條推導一起存入 frequency_plan.csv、欲收/鏡像兩條路徑、預選器查核表。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from Raised-cosine passband bandwidth is B=(1+alpha)Rs; increasing roll-off lowers symbol rate at fixed bandwidth., expand baseline expression 2400000/(1+0.2); record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Substitute both symbol rates into the bandwidth equation to recover 2.4 MHz; mark signed frequencies and the passband definition. Save both derivations with pulse_budget.csv, a spectral-boundary diagram and an ISI test list.","Starting from A difference mixer produces abs(fRF-fLO); with high-side injection, desired and image RF can share an IF and cannot be separated afterward by the IF filter., expand baseline expression 100+2*10; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Enumerate the mixer differences: 100 and 120 relative to 110 both give 10; 100 and 140 relative to 120 both give 20. Save both derivations with frequency_plan.csv, desired/image paths and a preselector checklist.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"comm-v28-082","referenceUrls":["https://www.etsi.org/deliver/etsi_ts/145000_145099/145002/15.02.00_60/ts_145002v150200p.pdf"],"title":"GPRS 多時槽：上下行資源守恆","titleEn":"GPRS multislot: uplink/downlink resource conservation","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 2000000 symbol/s 與 1600000 symbol/s，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 2000000 symbol/s and 1600000 symbol/s, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋48 kbit/s與36 kbit/s，建立gprs_slot_map.csv、能力假設、淨位元帳本，並完成以下驗收：需求40 kbit/s時只有4槽名義配置足夠；若能力或轉向限制禁止該配置，必須重設需求。","differenceEn":"Derive and explain 48 kbit/s and 36 kbit/s; create gprs_slot_map.csv, capability assumptions and useful-bit ledger; apply this acceptance decision: Only four slots meet a40 kbit/s nominal target; revise the demand if capability or turnaround constraints forbid that assignment.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 升餘弦通帶所需頻寬 B=(1+alpha)Rs；固定頻寬時滾降增加會降低可容納符元率。 展開基準式 2400000/(1+0.2)；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：把兩個符元率代回頻寬式，均應得到2.4 MHz；用頻譜圖標出正負頻率與通帶定義。 將兩條推導一起存入 pulse_budget.csv、頻譜邊界圖、ISI待測清單。","從原理 分配給封包的時槽受終端能力與方向切換約束；單槽有效率乘槽數只是固定條件模型。 展開基準式 12*4；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：建立8槽配置圖並標UL/DL/空閒，逐筆累加淨資料；不將編碼前符元率當12 kbit/s。 將兩條推導一起存入 gprs_slot_map.csv、能力假設、淨位元帳本。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from Raised-cosine passband bandwidth is B=(1+alpha)Rs; increasing roll-off lowers symbol rate at fixed bandwidth., expand baseline expression 2400000/(1+0.2); record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Substitute both symbol rates into the bandwidth equation to recover 2.4 MHz; mark signed frequencies and the passband definition. Save both derivations with pulse_budget.csv, a spectral-boundary diagram and an ISI test list.","Starting from Packet timeslots are constrained by terminal capability and direction switching; per-slot goodput times slot count is only a fixed-condition model., expand baseline expression 12*4; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Draw eight slots labeled UL/DL/idle and sum useful bits; do not confuse the12 kbit/s assumption with uncoded symbol rate. Save both derivations with gprs_slot_map.csv, capability assumptions and useful-bit ledger.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v28-case-1c7c0c3c35327e42","url":"https://www.analog.com/en/resources/technical-articles/system-noisefigure-analysis-for-modern-radio-receivers.html","title":"System Noise-Figure Analysis for Modern Radio Receivers","titleEn":"System Noise-Figure Analysis for Modern Radio Receivers","publisher":"Analog Devices","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v28-case-b12237ac3fc60f0b","url":"https://www.etsi.org/deliver/etsi_ts/145000_145099/145002/15.02.00_60/ts_145002v150200p.pdf","title":"ETSI TS 145 002 V15.2.0: GSM/EDGE Multiplexing and multiple access","titleEn":"ETSI TS 145 002 V15.2.0: GSM/EDGE Multiplexing and multiple access","publisher":"ETSI / 3GPP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
